import {SafeAreaView} from 'react-native-safe-area-context';
import Header from './components/Header';
import {ScrollView, View} from 'react-native';
import Body from './components/Body';
import styles from './styles';
import OverviewDocument from './components/OverviewDocument';
import {useEffect, useState} from 'react';
import {INumberReceipt} from '../../screen/dashboard';
import {useCatalogService} from '../../../hooks/apiHooks/useAPI';
import {useConfigStore} from '../zustand/config';
import {useOriginServices} from '../../../hooks/apiHooks/useOriginServices';
import {useAppSelector} from '../../../hooks/useRedux';

const DashboardEQDTHA = () => {
  const [numberReceipt, setNumberReceipt] = useState<INumberReceipt>({
    numberReceipt: 0,
    numberNumberingReceipt: 0,
    numberReceiptProcessing: 0,
    numberReceiptReleased: 0,
    numberReceiptFundSubmited: 0,
    numberReceiptPendingFundSubmited: 0,
  });
  const {setListAPPLICATION_STATUS, setListOrg} = useConfigStore();
  const CatalogService = useCatalogService();
  const OrgService = useOriginServices();

  const {dataAccount} = useAppSelector(state => state.account);

  useEffect(() => {
    handleInit();
  }, []);

  const getListAppStatus = async () => {
    const data = await CatalogService.getAppStatus();
    if (data) {
      setListAPPLICATION_STATUS(
        data.map((d: any) => ({
          id: d.id,
          label: d?.['textField_input-1'],
          value: d?.['textField_input-2'],
          color: d?.['textField_input-3'],
          bgColor: d?.['textField_input-4'],
        })),
      );
    }
    return data;
  };

  const getListDataOrg = async () => {
    const orgInSrc = dataAccount?.orgIn?.split('/').slice(0, 3).join('/');
    const data = await OrgService.getDataOrgByOrgin(orgInSrc);
    if (data) {
      setListOrg(
        data.map((o: any) => ({
          ...o,
          label: o?.name,
          value: o?.orgIn,
        })),
      );
    }
  };

  const handleInit = async () => {
    Promise.all([getListAppStatus(), getListDataOrg()]);
  };

  return (
    <>
      <SafeAreaView edges={[]} style={styles.ctnMain}>
        <Header />
        <ScrollView
          style={styles.mainContainer}
          showsVerticalScrollIndicator={false}>
          <View style={styles.body}>
            <Body />
            {/* <OverviewDocument numberReceipt={numberReceipt} /> */}
          </View>
        </ScrollView>
      </SafeAreaView>
    </>
  );
};

export default DashboardEQDTHA;
